-- slc.semantic.wwi_stock_by_stock_group (governed profile). Generated by build_metric_views.py.
CREATE OR REPLACE VIEW slc.semantic.wwi_stock_by_stock_group
WITH METRICS
LANGUAGE YAML
AS $$
version: 1.1
comment: Daily stock snapshot expanded to one row per stock group of each item (W-M2, W-C2 by stock group). Group values overlap.
source: |
  SELECT d.*, b.stock_group_id
  FROM (
    SELECT h.snapshot_date, h.wwi_stock_item_id, h.stock_item_key, h.quantity_on_hand, h.balance_basis,
      s.units_sold
    FROM slc.wwi.fact_stock_holding_daily h
    LEFT JOIN (
      SELECT si.wwi_stock_item_id, f.invoice_date, SUM(f.quantity) AS units_sold
      FROM slc.wwi.fact_sale f
      JOIN slc.wwi.dim_stock_item si ON si.stock_item_key = f.stock_item_key
      GROUP BY si.wwi_stock_item_id, f.invoice_date
    ) s ON s.wwi_stock_item_id = h.wwi_stock_item_id AND s.invoice_date = h.snapshot_date
  ) d
  JOIN slc.wwi.bridge_stock_item_group b ON b.wwi_stock_item_id = d.wwi_stock_item_id
joins:
- name: item
  source: slc.wwi.dim_stock_item
  'on': source.stock_item_key = item.stock_item_key
  rely:
    at_most_one_match: true
- name: grp
  source: slc.wwi.dim_stock_group
  'on': source.stock_group_id = grp.stock_group_id
  rely:
    at_most_one_match: true
fields:
- name: snapshot_date
  expr: source.snapshot_date
  comment: Snapshot date; the order field of every window measure in this view.
  display_name: Snapshot Date
- name: snapshot_year
  expr: CAST(DATE_TRUNC('YEAR', snapshot_date) AS DATE)
  comment: First day of the snapshot's calendar year.
  display_name: Snapshot Year
- name: snapshot_quarter
  expr: CAST(DATE_TRUNC('QUARTER', snapshot_date) AS DATE)
  comment: First day of the snapshot's calendar quarter.
  display_name: Snapshot Quarter
- name: snapshot_month
  expr: CAST(DATE_TRUNC('MONTH', snapshot_date) AS DATE)
  comment: First day of the snapshot's calendar month.
  display_name: Snapshot Month
- name: snapshot_fiscal_year
  expr: YEAR(snapshot_date) + CASE WHEN MONTH(snapshot_date) >= 11 THEN 1 ELSE 0 END
  comment: Fiscal year (starting 1 November) of the snapshot date.
  display_name: Snapshot Fiscal Year
- name: stock_item
  expr: item.stock_item
  comment: Product as recorded at the time of sale (SCD Type 2); current attributes via the durable item id.
  display_name: Stock Item
  synonyms:
  - product
  - item
  - SKU
  - article
- name: wwi_stock_item_id
  expr: item.wwi_stock_item_id
  comment: Durable stock item id (stable across SCD Type 2 versions).
  display_name: WWI Stock Item ID
- name: brand
  expr: item.brand
  display_name: Brand
- name: color
  expr: item.color
  comment: Color as recorded at the time of the fact (as-was).
  display_name: Color
- name: size
  expr: item.size
  display_name: Size
- name: selling_package
  expr: item.selling_package
  display_name: Selling Package
- name: is_chiller_stock
  expr: item.is_chiller_stock
  display_name: Is Chiller Stock
- name: stock_group
  expr: grp.stock_group_name
  comment: Product group; an item can belong to several groups, so group totals overlap.
  display_name: Stock Group
  synonyms:
  - category
  - product group
  - product category
  - department
measures:
- name: closing_units
  expr: SUM(quantity_on_hand)
  comment: Units on hand on the last day of the period (semi-additive); summed across stock items and stock groups.
  display_name: Closing Stock On Hand
  format:
    type: number
    decimal_places:
      type: exact
      places: 0
  synonyms:
  - stock on hand
  - inventory
  - closing inventory
  - ending inventory
  - units in stock
  window:
  - order: snapshot_date
    range: current
    semiadditive: last
- name: units_sold_91d
  expr: SUM(units_sold)
  comment: Units sold in the 91 days ending on the period end (t - 90 .. t).
  display_name: Units Sold (Trailing 91 Days)
  format:
    type: number
    decimal_places:
      type: exact
      places: 0
  synonyms:
  - 91 day sales
  - trailing quarter sales
  window:
  - order: snapshot_date
    range: trailing 91 day inclusive
    semiadditive: last
- name: days_of_supply
  expr: CAST(MEASURE(closing_units) AS DOUBLE) / NULLIF(CAST(MEASURE(units_sold_91d) AS DOUBLE) / 91, 0)
  comment: Closing Stock On Hand divided by average daily Units Sold over the 91 days ending on the period end. Defined only
    by date and stock item attributes.
  display_name: Days of Supply
  format:
    type: number
    decimal_places:
      type: exact
      places: 1
  synonyms:
  - DOS
  - days of inventory
  - inventory cover
  - stock cover
  - weeks of supply
$$;
